import{_ as s,C as n,o as e,c as d,j as i,a as o,E as t,a3 as l}from"./chunks/framework.C6R8kWFE.js";const P=JSON.parse(`{"title":"7-dars (Mentor). Klaviaturada tez va to‘g‘ri yozish ko‘nikmalari (Touch typing)","description":"","frontmatter":{"title":"7-dars (Mentor). Klaviaturada tez va to‘g‘ri yozish ko‘nikmalari (Touch typing)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":3,"link":"/mentor/8-sinf-cs/hafta-03/"},"g":7,"title":"Klaviaturada tez va to‘g‘ri yozish ko‘nikmalari (Touch typing)","lead":"Klaviaturaga qaramasdan 10 barmoqda chaqqon yozish san'ati, F va J sirlari, to'g'ri gavda ergonomikasi va yozish tezligini oshirish mashqlari.","slide":"/slaydlar/8-sinf-cs/hafta-03/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-03/dars-1-test.html","student_link":"/8-sinf-cs/hafta-03/dars-1","tabs":[{"g":7,"link":"/mentor/8-sinf-cs/hafta-03/dars-1","current":true},{"g":8,"link":"/mentor/8-sinf-cs/hafta-03/dars-2","current":false},{"g":9,"link":"/mentor/8-sinf-cs/hafta-03/dars-3","current":false}],"prev":null,"next":{"g":8,"title":"Raqamli savodxonlik va raqamli madaniyat","link":"/mentor/8-sinf-cs/hafta-03/dars-2"}}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-03/dars-1.md","filePath":"mentor/8-sinf-cs/hafta-03/dars-1.md"}`),h={name:"mentor/8-sinf-cs/hafta-03/dars-1.md"},g={class:"blk"},c={id:"_1-dars-rejasi",tabindex:"-1"},k={class:"blk"},m={id:"_2-konspekt",tabindex:"-1"},u={class:"blk"},q={id:"_3-amaliy-topshiriqlar-va-yechimlari",tabindex:"-1"},b={class:"blk"},v={id:"_4-tezkor-nazorat-savollari-javoblari-bilan",tabindex:"-1"};function y(z,a,p,f,_,T){const r=n("Icon");return e(),d("div",null,[a[12]||(a[12]=i("p",null,[i("strong",null,"Hafta:"),o(" 3 · "),i("strong",null,"Davomiyligi:"),o(" 80 daqiqa · "),i("strong",null,"Turi:"),o(" nazariya + amaliy trenajyor · "),i("strong",null,"II-bob"),o(", 7-dars")],-1)),i("div",g,[i("h2",c,[t(r,{name:"file-text"}),a[0]||(a[0]=o(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=l('<p><strong>Maqsad:</strong> o&#39;quvchilarga klaviatura tuzilishi, kompyuterda ishlashda to&#39;g&#39;ri o&#39;tirish (ergonomika), klaviaturaga qaramasdan 10 barmoqda yozish («Touch typing» usuli) texnikasi, tayanch klavishlar (ASDF - JKL;) va F/J bo&#39;rtiqlari vazifasi hamda klaviatura trenajyorlari orqali yozish tezligi (WPM) va aniqligini oshirishni amaliy o&#39;rgatish.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Klaviaturaning asosiy guruhlarini (alfavit-raqam, funksional, maxsus boshqaruv, kursor) ajrata oladi.</li><li>Ergonomika qoidalariga (gavda holati, ko&#39;zdan monitorgacha masofa 50–70 sm, bilak holati) to&#39;liq rioya qiladi.</li><li>10 barmoqning har biriga biriktirilgan klavishlar zonasini biladi va barmoqlarni tayanch (Home row) qatoriga to&#39;g&#39;ri joylashtiradi.</li><li>Klaviaturaga qaramasdan F va J dagi taktil bo&#39;rtiqlar orqali boshlang&#39;ich pozitsiyani topa oladi.</li><li>WPM (Words Per Minute) va aniqlik (Accuracy) metrikalarini tushunadi, klaviatura trenajyorida kamida 15–20 WPM tezlikda mashq bajaradi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Kirish va qiziqtirish</td><td>I bob xulosasi. «Dunyodagi eng tez yozuvchi inson daqiqasiga 216 ta so&#39;z yozadi. Nega 2 barmoqda yozish xato?»</td></tr><tr><td>10–30 daq</td><td>Yangi mavzu: Nazariya</td><td>Klaviatura tuzilishi, ergonomika, 10 barmoq xaritasi, F va J siri</td></tr><tr><td>30–35 daq</td><td>Tanaffus</td><td>Qo&#39;l, barmoq va bo&#39;yin mashqlari</td></tr><tr><td>35–65 daq</td><td>Amaliy trenajyor</td><td>TypingClub / Keybr / Ratatype platformalarida boshlang&#39;ich darslarni bajarish</td></tr><tr><td>65–75 daq</td><td>Tezkor sinov</td><td>1 daqiqalik tezlik testi (WPM o&#39;lchash) va 5 ta savol</td></tr><tr><td>75–80 daq</td><td>Xulosa va vazifa</td><td>Natijalarni tahlil qilish va uyga vazifani tushuntirish</td></tr></tbody></table><hr>',5))]),i("div",k,[i("h2",m,[t(r,{name:"file-text"}),a[3]||(a[3]=o(" 2. Konspekt ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-konspekt","aria-label":'Permalink to "<Icon name="file-text" /> 2. Konspekt"'},"​",-1))]),a[5]||(a[5]=l('<h3 id="_2-1-klaviatura-anatomiyasi-va-tugmalar-guruhlari" tabindex="-1">2.1. Klaviatura anatomiyasi va tugmalar guruhlari <a class="header-anchor" href="#_2-1-klaviatura-anatomiyasi-va-tugmalar-guruhlari" aria-label="Permalink to &quot;2.1. Klaviatura anatomiyasi va tugmalar guruhlari&quot;">​</a></h3><p>Klaviatura — kompyuterga axborot va buyruqlarni kiritishning eng asosiy apparat vositasi. Standart klaviatura (QWERTY) 101–105 ta tugmadan iborat bo&#39;lib, 5 ta asosiy guruhga bo&#39;linadi:</p><ol><li><strong>Alfavit-raqamli klavishlar:</strong> Harflar, raqamlar, tinish belgilari va Probel (Space).</li><li><strong>Funksional klavishlar (<code>F1</code> – <code>F12</code>):</strong> Har bir dasturda o&#39;ziga xos tezkor vazifani bajaradi (masalan: <code>F1</code> — yordam, <code>F5</code> — yangilash).</li><li><strong>Boshqaruv klavishlari:</strong> <code>Ctrl</code>, <code>Alt</code>, <code>Shift</code>, <code>Windows (Win)</code>, <code>Esc</code>, <code>Caps Lock</code>, <code>Tab</code>.</li><li><strong>Navigatsiya va tahrir klavishlari:</strong> Strelkalar, <code>Home</code>, <code>End</code>, <code>Page Up</code>, <code>Page Down</code>, <code>Insert</code>, <code>Delete</code>, <code>Backspace</code>.</li><li><strong>Raqamli blok (Numpad):</strong> Klaviaturaning o&#39;ng tomonidagi kalkulyatorga o&#39;xshash raqamlar bloki (<code>Num Lock</code> bilan yoqiladi).</li></ol><h3 id="_2-2-ergonomika-to-g-ri-o-tirish-qoidalari" tabindex="-1">2.2. Ergonomika: To&#39;g&#39;ri o&#39;tirish qoidalari <a class="header-anchor" href="#_2-2-ergonomika-to-g-ri-o-tirish-qoidalari" aria-label="Permalink to &quot;2.2. Ergonomika: To&#39;g&#39;ri o&#39;tirish qoidalari&quot;">​</a></h3><p>Soatlab kompyuter qarshisida noto&#39;g&#39;ri o&#39;tirish umurtqa pog&#39;onasi qiyshayishiga, ko&#39;z xiralashishiga va bilak kasalliklariga (tunnel sindromi) olib keladi:</p><ul><li><strong>Ko&#39;z va monitor:</strong> Ekran ko&#39;zdan 50–70 sm (cho&#39;zilgan qo&#39;l masofasida) uzoqlikda va ko&#39;z balandligidan biroz pastroqda turishi kerak.</li><li><strong>Gavda holati:</strong> Orqa suyanchiqqa to&#39;g&#39;ri tegib turishi, yelkalar erkin va tushirilgan bo&#39;lishi lozim.</li><li><strong>Tirsak va oyoq:</strong> Tirsaklar va tizzalar taxminan 90 daraja burchak ostida bukiladi, oyoq kafti to&#39;liq polga tegib turadi.</li><li><strong>Bilaklar:</strong> Klaviaturaga osilib yoki qattiq bosilib turmasligi, stol ustida tekis va erkin harakatlanishi shart.</li></ul><h3 id="_2-3-touch-typing-10-barmoqda-ko-rmasdan-yozish-usuli" tabindex="-1">2.3. Touch Typing (10 barmoqda ko&#39;rmasdan yozish) usuli <a class="header-anchor" href="#_2-3-touch-typing-10-barmoqda-ko-rmasdan-yozish-usuli" aria-label="Permalink to &quot;2.3. Touch Typing (10 barmoqda ko&#39;rmasdan yozish) usuli&quot;">​</a></h3><p>Ko&#39;pchilik odamlar 2 ta ko&#39;rsatkich barmog&#39;i bilan klaviaturaga qarab («tovuq donlagandek») yozishadi. Bu usulda tezlik kamdan-kam 30 WPM dan oshadi va ko&#39;z doim monitor bilan klaviatura orasida charchaydi.</p><p><strong>Touch Typing</strong> — bu klaviaturaga umuman qaramasdan, barmoqlarning mushak xotirasi (muscle memory) orqali yozish san&#39;atidir:</p><ol><li><strong>Tayanch qator (Home Row):</strong><ul><li>Chap qo&#39;l: <code>A</code> (jimjiloq), <code>S</code> (nomsiz), <code>D</code> (o&#39;rta), <code>F</code> (ko&#39;rsatkich).</li><li>O&#39;ng qo&#39;l: <code>J</code> (ko&#39;rsatkich), <code>K</code> (o&#39;rta), <code>L</code> (nomsiz), <code>;</code> (jimjiloq).</li><li>Ikkala bosh barmoq: faqat <strong>Probel (Space)</strong> tugmasida turadi.</li></ul></li><li><strong>F va J bo&#39;rtiqlari:</strong><ul><li>Har qanday standart klaviaturaning <code>F</code> va <code>J</code> harflarida kichik gorizontal chiziqcha yoki nuqtacha (taktil bo&#39;rtiq) bor. Ular ko&#39;rmasdan turib ikkala ko&#39;rsatkich barmog&#39;ini darhol o&#39;z uyasiga joylashtirish uchun mo&#39;ljallangan!</li></ul></li><li><strong>Asosiy qoida:</strong> Har bir barmoq o&#39;ziga biriktirilgan hududdagi klavishni bosadi va darhol o&#39;zining tayanch qatoridagi joyiga qaytadi. Klaviaturaga qaramaslik — eng asosiy qoidadir!</li></ol><h3 id="_2-4-tezlik-va-aniqlik-metrikalari-wpm-va-accuracy" tabindex="-1">2.4. Tezlik va aniqlik metrikalari: WPM va Accuracy <a class="header-anchor" href="#_2-4-tezlik-va-aniqlik-metrikalari-wpm-va-accuracy" aria-label="Permalink to &quot;2.4. Tezlik va aniqlik metrikalari: WPM va Accuracy&quot;">​</a></h3><ul><li><strong>WPM (Words Per Minute / Daqiqasiga so&#39;zlar soni):</strong> Xalqaro standart bo&#39;yicha 1 ta so&#39;z o&#39;rtacha 5 ta belgi (harf, belgi, probel) deb hisoblanadi. <ul><li>10–20 WPM: Boshlang&#39;ich daraja;</li><li>30–45 WPM: O&#39;rtacha foydalanuvchi darajasi;</li><li>50–70 WPM: Tajribali dasturchi yoki operator;</li><li>80+ WPM: Professional tezkor yozuvchi.</li></ul></li><li><strong>Accuracy (Aniqlik foizi):</strong> Yozilgan so&#39;zlarning necha foizi xatosiz ekanligi. Qoida: <strong>Avval aniqlik, keyin tezlik!</strong> Aniqlik 95% dan past bo&#39;lsa, tezlikni oshirish foydasiz, chunki Backspace bosish ko&#39;p vaqt o&#39;g&#39;irlaydi.</li></ul><hr>',13))]),i("div",u,[i("h2",q,[t(r,{name:"file-text"}),a[6]||(a[6]=o(" 3. Amaliy topshiriqlar va yechimlari ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-amaliy-topshiriqlar-va-yechimlari","aria-label":'Permalink to "<Icon name="file-text" /> 3. Amaliy topshiriqlar va yechimlari"'},"​",-1))]),a[8]||(a[8]=l('<h3 id="_1-topshiriq-home-row-tayanch-qatori-pozitsiyasini-o-rnatish" tabindex="-1">1-topshiriq. Home Row (Tayanch qatori) pozitsiyasini o&#39;rnatish <a class="header-anchor" href="#_1-topshiriq-home-row-tayanch-qatori-pozitsiyasini-o-rnatish" aria-label="Permalink to &quot;1-topshiriq. Home Row (Tayanch qatori) pozitsiyasini o&#39;rnatish&quot;">​</a></h3><p><strong>Vazifa:</strong> Ko&#39;zingizni yuming. Faqat barmoq sezgisi bilan <code>F</code> va <code>J</code> bo&#39;rtiqlarini toping va 8 ta barmog&#39;ingizni <code>ASDF - JKL;</code> qatoriga joylashtiring. <strong>Yechim:</strong></p><ul><li>Ko&#39;rsatkich barmoqlar klaviatura bo&#39;ylab siljiganda <code>F</code> va <code>J</code> dagi qavariq chiziqchalar seziladi.</li><li>Chap qo&#39;l: Jimjiloq <code>A</code>, nomsiz <code>S</code>, o&#39;rta <code>D</code>, ko&#39;rsatkich <code>F</code>.</li><li>O&#39;ng qo&#39;l: Ko&#39;rsatkich <code>J</code>, o&#39;rta <code>K</code>, nomsiz <code>L</code>, jimjiloq <code>;</code> (yoki ruscha klaviaturada <code>Ж</code>).</li><li>Bosh barmoqlar Probelda erkin turadi.</li></ul><h3 id="_2-topshiriq-boshlang-ich-trenajyor-mashqi" tabindex="-1">2-topshiriq. Boshlang&#39;ich trenajyor mashqi <a class="header-anchor" href="#_2-topshiriq-boshlang-ich-trenajyor-mashqi" aria-label="Permalink to &quot;2-topshiriq. Boshlang&#39;ich trenajyor mashqi&quot;">​</a></h3><p><strong>Vazifa:</strong> Bloknot (Notepad) dasturini oching. Klaviaturaga qaramasdan quyidagi harflar ketma-ketligini 3 qatordan yozing: <code>asdf jkl; asdf jkl; f f j j fj fj d k s l a ;</code><strong>Yechim:</strong></p><ul><li>Har bir harf faqat o&#39;z barmog&#39;i bilan bosiladi. Xato bo&#39;lsa darhol to&#39;xtab barmoq o&#39;rnini tekshirish lozim.</li></ul><h3 id="_3-topshiriq-1-daqiqalik-wpm-tezlik-testi" tabindex="-1">3-topshiriq. 1 daqiqalik WPM tezlik testi <a class="header-anchor" href="#_3-topshiriq-1-daqiqalik-wpm-tezlik-testi" aria-label="Permalink to &quot;3-topshiriq. 1 daqiqalik WPM tezlik testi&quot;">​</a></h3><p><strong>Vazifa:</strong> Bepul onlayn trenajyorga (masalan: <code>ratatype.com</code> yoki <code>typingclub.com</code>) kiring va 1 daqiqalik matn terish testidan o&#39;ting. O&#39;z WPM tezligingiz va Aniqlik (Accuracy) natijangizni qayd eting. <strong>Yechim:</strong></p><ul><li>O&#39;quvchi testdan o&#39;tadi va masalan quyidagi natijani oladi: <em>Tezlik: 18 WPM, Aniqlik: 96%</em>.</li></ul><hr>',10))]),i("div",b,[i("h2",v,[t(r,{name:"file-text"}),a[9]||(a[9]=o(" 4. Tezkor nazorat savollari (javoblari bilan) ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-tezkor-nazorat-savollari-javoblari-bilan","aria-label":'Permalink to "<Icon name="file-text" /> 4. Tezkor nazorat savollari (javoblari bilan)"'},"​",-1))]),a[11]||(a[11]=l("<ol><li><strong>Savol:</strong> Nima sababdan <code>F</code> va <code>J</code> tugmalarida maxsus bo&#39;rtiqlar bor? <strong>Javob:</strong> Klaviaturaga qaramasdan (ko&#39;rmasdan) ko&#39;rsatkich barmoqlarni tayanch (Home Row) qatoriga to&#39;g&#39;ri joylashtirish uchun taktil nishon vazifasini bajaradi.</li><li><strong>Savol:</strong> WPM qisqartmasi nimani anglatadi va u qanday o&#39;lchanadi? <strong>Javob:</strong> WPM — «Words Per Minute» (daqiqasiga so&#39;zlar soni). 1 ta so&#39;z o&#39;rtacha 5 ta belgi deb qabul qilinadi.</li><li><strong>Savol:</strong> Kompyuterda o&#39;tirganda ko&#39;zdan ekrangacha bo&#39;lgan to&#39;g&#39;ri masofa qancha bo&#39;lishi kerak? <strong>Javob:</strong> 50–70 santimetr (taxminan bir cho&#39;zilgan qo&#39;l masofasida).</li><li><strong>Savol:</strong> Probel (Space) tugmasi qaysi barmoq bilan bosiladi? <strong>Javob:</strong> Ikkala qo&#39;lning bosh barmoqlari bilan (qaysi biri qulay bo&#39;lsa).</li><li><strong>Savol:</strong> Nima uchun Touch typing&#39;da avval tezlikka emas, aniqlikka e&#39;tibor qaratish kerak? <strong>Javob:</strong> Agar xato ko&#39;p bo&#39;lsa, Backspace bosib xatoni tuzatishga ikki barobar ko&#39;p vaqt sarflanadi. Aniqlik 95%+ bo&#39;lgach, tezlik o&#39;z-o&#39;zidan o&#39;sadi.</li></ol>",1))])])}const x=s(h,[["render",y]]);export{P as __pageData,x as default};
